package com.nivor.notification;import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.notification.NotificationDtos.*;import com.nivor.user.UserService;import java.time.LocalDateTime;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service@Transactional public class NotificationService{private final NotificationRepository repo;private final UserService users;public NotificationService(NotificationRepository r,UserService u){repo=r;users=u;}public List<View> list(String email,boolean unreadOnly){long id=users.getByEmail(email).getId();return (unreadOnly?repo.findAllByUser_IdAndReadFalseOrderByCreatedAtDesc(id):repo.findAllByUser_IdOrderByCreatedAtDesc(id)).stream().limit(100).map(View::from).toList();}public UnreadCount count(String e){return new UnreadCount(repo.countByUser_IdAndReadFalse(users.getByEmail(e).getId()));}public View read(String e,long id){Notification n=owned(e,id);n.setRead(true);return View.from(n);}public long readAll(String e){List<Notification> unread=repo.findAllByUser_IdAndReadFalseOrderByCreatedAtDesc(users.getByEmail(e).getId());unread.forEach(n->n.setRead(true));return unread.size();}public void delete(String e,long id){repo.delete(owned(e,id));}public void create(com.nivor.user.User user,NotificationType type,String title,String message,String entity,Long entityId){if(entityId!=null&&repo.existsByUser_IdAndTypeAndRelatedEntityIdAndCreatedAtAfter(user.getId(),type,entityId,LocalDateTime.now().minusDays(2)))return;Notification n=new Notification();n.setUser(user);n.setType(type);n.setTitle(title);n.setMessage(message);n.setRelatedEntityType(entity);n.setRelatedEntityId(entityId);repo.save(n);}private Notification owned(String e,long id){return repo.findByIdAndUser_Id(id,users.getByEmail(e).getId()).orElseThrow(()->new ResourceNotFoundException("Notification not found"));}}
